/**
 * Document furniture for CLIENT-side printed documents.
 *
 * The browser builds the per-module print views, but the header/footer must read exactly
 * like a server-rendered report PDF (see backend/src/utils/reportHeader.ts): org name +
 * logo on the left, document title + reference on the right, and a single
 * "Generated By: <name> (<empId>) | Generated: <IST>" attribution line.
 *
 * Org branding lives in SystemConfig, so it is fetched once and cached here. `printHtml`
 * is synchronous (it opens a window immediately), so it reads this cache rather than
 * awaiting — the cache is primed at app start. If it has not arrived yet the document
 * still prints, just without the org name/logo, which is better than blocking the print.
 */
import { api } from '@/lib/axios';

export interface Branding {
  orgName: string;
  logoPath: string;
  timezone: string;
}

let cached: Branding | null = null;
let inFlight: Promise<Branding | null> | null = null;

/** Fetch and cache org branding. Safe to call repeatedly; only one request is made. */
export function loadBranding(): Promise<Branding | null> {
  if (cached) return Promise.resolve(cached);
  if (inFlight) return inFlight;
  inFlight = api
    .get('/system-config/branding')
    .then((r) => {
      cached = (r.data?.data ?? null) as Branding | null;
      return cached;
    })
    .catch(() => null) // printing must never fail because branding could not be read
    .finally(() => {
      inFlight = null;
    });
  return inFlight;
}

/** Synchronous read for printHtml. Null until loadBranding() has resolved. */
export function getBranding(): Branding | null {
  return cached;
}

/** Cleared on logout so the next user/org does not inherit stale branding. */
export function clearBranding(): void {
  cached = null;
}
